$countryAsset = static fn (string $flagCode): array => [
    'asset_status' => 'placeholder',
    'flag_code' => $flagCode,
    'official_logo_path' => null,
    'placeholder' => true,
    'placeholder_label' => $flagCode,
];

$catalogAsset = static function (string $label): array {
    $letters = preg_replace('/[^A-Za-z0-9]+/', '', $label) ?: $label;

    return [
        'asset_status' => 'placeholder',
        'official_logo_path' => null,
        'placeholder' => true,
        'placeholder_label' => mb_strtoupper(mb_substr($letters, 0, 2)),
    ];
};

$country = static fn (string $label, string $regionKey, string $iso2, int $priority, string $sourceStatus = 'needs_review'): array => [
    'label' => $label,
    'region_key' => $regionKey,
    'iso2' => $iso2,
    'priority' => $priority,
    'source_status' => $sourceStatus,
    'source_urls' => [],
    'asset_status' => 'placeholder',
    'asset_meta' => $countryAsset($iso2),
];

$competition = static function (
    string $regionKey,
    string $countryKey,
    string $competitionKey,
    string $label,
    string $shortLabel,
    string $tier,
    string $identityTier,
    string $publicSurface,
    int $priority,
    array $aliases = [],
    string $sourceStatus = 'needs_review',
    array $sourceUrls = [],
    ?string $legacyKey = null
) use ($catalogAsset): array {
    $legacyKey ??= in_array($countryKey, ['fifa', 'uefa', 'conmebol', 'concacaf', 'caf'], true)
        ? $competitionKey
        : $countryKey . '_' . $competitionKey;

    return [
        'competition_key' => $competitionKey,
        'legacy_key' => $legacyKey,
        'sport_group_key' => 'soccer',
        'region_key' => $regionKey,
        'country_key' => $countryKey,
        'label' => $label,
        'short_label' => $shortLabel,
        'tier' => $tier,
        'identity_tier' => $identityTier,
        'public_surface' => $publicSurface,
        'priority' => $priority,
        'visibility' => 'visible',
        'shell_enabled' => true,
        'source_status' => $sourceStatus,
        'source_urls' => $sourceUrls,
        'asset_status' => 'placeholder',
        'asset_meta' => $catalogAsset($label),
        'aliases' => array_values(array_unique(array_filter(array_merge([$label, $shortLabel, $legacyKey], $aliases)))),
    ];
};

$team = static function (
    string $countryKey,
    string $teamKey,
    string $label,
    string $shortLabel,
    array $competitionKeys,
    string $tier = 'standard',
    array $aliases = [],
    string $sourceStatus = 'needs_review'
) use ($catalogAsset): array {
    return [
        'team_key' => $teamKey,
        'sport_group_key' => 'soccer',
        'country_key' => $countryKey,
        'label' => $label,
        'short_label' => $shortLabel,
        'tier' => $tier,
        'visibility' => 'visible',
        'competition_keys' => $competitionKeys,
        'source_status' => $sourceStatus,
        'source_urls' => [],
        'asset_status' => 'placeholder',
        'asset_meta' => $catalogAsset($label),
        'aliases' => array_values(array_unique(array_filter(array_merge([$label, $shortLabel], $aliases)))),
    ];
};

$sportCompetition = static function (
    string $sportGroupKey,
    string $regionKey,
    string $countryKey,
    string $competitionKey,
    string $label,
    string $shortLabel,
    string $tier,
    string $identityTier,
    string $publicSurface,
    int $priority,
    array $aliases = [],
    string $sourceStatus = 'needs_review',
    array $sourceUrls = [],
    ?string $legacyKey = null,
    array $meta = []
) use ($catalogAsset): array {
    $legacyKey ??= $countryKey . '_' . $competitionKey;

    return [
        'competition_key' => $competitionKey,
        'legacy_key' => $legacyKey,
        'sport_group_key' => $sportGroupKey,
        'region_key' => $regionKey,
        'country_key' => $countryKey,
        'label' => $label,
        'short_label' => $shortLabel,
        'tier' => $tier,
        'identity_tier' => $identityTier,
        'public_surface' => $publicSurface,
        'priority' => $priority,
        'visibility' => 'visible',
        'shell_enabled' => true,
        'source_status' => $sourceStatus,
        'source_urls' => $sourceUrls,
        'asset_status' => 'placeholder',
        'asset_meta' => $catalogAsset($label),
        'meta' => $meta,
        'aliases' => array_values(array_unique(array_filter(array_merge([$label, $shortLabel, $legacyKey], $aliases)))),
    ];
};

$sportTeam = static function (
    string $sportGroupKey,
    string $countryKey,
    string $teamKey,
